INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14345$nota-0280$m14345$, $m14346$Exercise Physiology McArdle.pdf$m14346$, $m14347$752$m14347$, $m14348$This means that on average for about 70 of every 100 people measured, the equations will predict body fat within the 2.5 to 4.0% body fat compared to the person's body fat had it been assessed by a valid criterion such as hydrostatic weighing, DXA, or BOD POD.$m14348$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14349$nota-0280$m14349$, $m14350$Exercise Physiology McArdle.pdf$m14350$, $m14351$751$m14351$, $m14352$Predict body fat in athletes from an equation validated against a four-component model... % Body fat = 8.997 + 0.24658 (3 SKF) − 6.343 (gender) − 1.998 (race), where 3 SKF = sum of skinfolds in mm at abdomen, thigh, and triceps; gender = 0 for female, 1 for male; race = 0 for white, 1 for black.$m14352$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14353$nota-0280$m14353$, $m14354$Exercise Physiology McArdle.pdf$m14354$, $m14355$748$m14355$, $m14356$Underprediction of body fat also occurred in a heterogeneous sample of black men... The method underpredicted percentage body fat compared with densitometry (–1.9% fat units) and DXA (–1.6% fat units). Similar underpredictions compared with DXA-derived body fat (–2.9% fat units) occurred in 54 boys and girls 10 to 18 years of age.$m14356$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14357$nota-0280$m14357$, $m14358$Exercise Physiology McArdle.pdf$m14358$, $m14359$761$m14359$, $m14360$Using a more robust model of body composition assessment, the error is less than 2% body fat units between DXA and densitometry in the heterogeneous age group of adults shown in the figure.$m14360$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14361$nota-0280$m14361$, $m14362$nota-0278$m14362$, $m14363$complementa$m14363$, $m14364$densitometria (base da equação de Siri) é um dos métodos-critério contra os quais os demais métodos são comparados nesta nota$m14364$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14365$nota-0280$m14365$, $m14366$nota-0279$m14366$, $m14367$complementa$m14367$, $m14368$BIA é outro método de composição corporal com erro sistemático próprio, tratado separadamente$m14368$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14369$nota-0003$m14369$, $m14370$Training and Racing with a Power Meter.pdf$m14370$, $m14371$28$m14371$, $m14372$it has been found that with improvements in positioning and equipment a rider should be able to pedal at approximately 30 watts less to maintain a given speed.$m14372$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14373$nota-0003$m14373$, $m14374$Training and Racing with a Power Meter.pdf$m14374$, $m14375$29$m14375$, $m14376$you may be able to gain 30 watts of power. This represents a greater gain than most cyclists see in an entire year of training.$m14376$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14377$nota-0005$m14377$, $m14378$Training and Racing with a Power Meter.pdf$m14378$, $m14379$21$m14379$, $m14380$Self-Assessment... Collaboration... Focused Training... Peak Performance: With accurate information, improved collaboration, and smarter training, you will be positioned to do your best in cycling.$m14380$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14381$nota-0035$m14381$, $m14382$Training and Racing with a Power Meter.pdf$m14382$, $m14383$75$m14383$, $m14384$The cyclist who is an all-rounder will have a generally horizontal plot across all the categories... The all-rounder does not necessarily excel at any one thing but is likely competitive in his or her category across a broad range of events.$m14384$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14385$nota-0035$m14385$, $m14386$Training and Racing with a Power Meter.pdf$m14386$, $m14387$76$m14387$, $m14388$A good sprinter will typically have a distinctly downward sloping plot, especially between the 1-minute and 5-minute categories.$m14388$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14389$nota-0035$m14389$, $m14390$Training and Racing with a Power Meter.pdf$m14390$, $m14391$76$m14391$, $m14392$A distinctly upward-sloping plot... is typical for the time trialist... most time trialists are weak in neuromuscular power and anaerobic capacity, but they have relatively high aerobic power and an especially high lactate threshold.$m14392$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14393$nota-0035$m14393$, $m14394$Training and Racing with a Power Meter.pdf$m14394$, $m14395$78$m14395$, $m14396$A sharply inverted V pattern implies both a relatively high anaerobic capacity and high aerobic ability, which makes a rider particularly well suited for events such as the pursuit.$m14396$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14397$nota-0035$m14397$, $m14398$nota-0031$m14398$, $m14399$pre-requisito$m14399$, $m14400$usa a classificação por categoria da Tabela 4.1 (nota-0031) nas 4 durações para desenhar o formato do perfil$m14400$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14401$nota-0036$m14401$, $m14402$Training and Racing with a Power Meter.pdf$m14402$, $m14403$78$m14403$, $m14404$The Power Profile standards are based on the performance capacities of young adults and thus do not account for the effects of aging... starting around age 30, an athlete's VO2max will decline year over year. For men, the annual rate of decline equates to roughly 0.5 ml/kg/min.; for women, VO2max declines at a slightly slower annual rate, about 0.35 ml/kg/min.$m14404$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14405$nota-0036$m14405$, $m14406$Training and Racing with a Power Meter.pdf$m14406$, $m14407$79$m14407$, $m14408$Muscular strength and power, in contrast, can generally be maintained, with training, until around age 50, but at that point they begin to decline somewhat more rapidly.$m14408$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14409$nota-0036$m14409$, $m14410$nota-0031$m14410$, $m14411$complementa$m14411$, $m14412$detalha uma limitação importante da Tabela 4.1 (Power Profile) da nota-0031$m14412$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14413$nota-0082$m14413$, $m14414$Training and Racing with a Power Meter.pdf$m14414$, $m14415$209$m14415$, $m14416$The key aspects of the Phenotypic Map are the ratios of Pmax/FTP and FRC/Pmax... If the Pmax/FTP ratio is low, this would be comparable to the upward-sloping classic Power Profile of the time trialist. On the other hand, a high Pmax/FTP would indicate the classic downward-sloping Power Profile of the sprinter.$m14416$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14417$nota-0082$m14417$, $m14418$Training and Racing with a Power Meter.pdf$m14418$, $m14419$211$m14419$, $m14420$since the time trialists will all have a relatively low Pmax, looking at the FRC/Pmax will identify the successful pursuiters.$m14420$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14421$nota-0082$m14421$, $m14422$nota-0035$m14422$, $m14423$alternativa-a$m14423$, $m14424$versão mais refinada (2D, contínua) dos fenótipos qualitativos (all-rounder, sprinter, contrarrelogista, perseguidor) descritos na nota-0035 a partir do Power Profile clássico$m14424$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14425$nota-0082$m14425$, $m14426$nota-0077$m14426$, $m14427$pre-requisito$m14427$, $m14428$usa o Pmax definido na nota-0077$m14428$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14429$nota-0082$m14429$, $m14430$nota-0078$m14430$, $m14431$pre-requisito$m14431$, $m14432$usa a FRC definida na nota-0078$m14432$)
